package servicio;
import java.sql.*;
import java.time.*;
import config.ConexionBD;
import dao.*;
import negocio.*;
public class IdentidadDeportivaService {
 private final PerfilJugadorDAO perfiles; private final CategoriaDeportivaDAO categorias; private final JugadorCategoriaDAO historial; private final ProveedorConexion conexiones;
 public IdentidadDeportivaService(){this(new PerfilJugadorDAOMySQL(),new CategoriaDeportivaDAOMySQL(),new JugadorCategoriaDAOMySQL(),ConexionBD::obtenerConexion);}
 public IdentidadDeportivaService(PerfilJugadorDAO p,CategoriaDeportivaDAO c,JugadorCategoriaDAO h,ProveedorConexion x){if(p==null||c==null||h==null||x==null)throw new IllegalArgumentException("Las dependencias son obligatorias.");perfiles=p;categorias=c;historial=h;conexiones=x;}
 public PerfilJugador crearDefinitivo(long clienteId,String nombre){if(clienteId<=0)throw new IllegalArgumentException("El cliente es inválido.");return guardar(nuevo(clienteId,EstadoPerfilJugador.DEFINITIVO,nombre));}
 public PerfilJugador crearProvisional(String nombre){return guardar(nuevo(null,EstadoPerfilJugador.PROVISIONAL,nombre));}
 private PerfilJugador nuevo(Long cliente,EstadoPerfilJugador estado,String nombre){PerfilJugador p=new PerfilJugador();p.setClienteId(cliente);p.setEstado(estado);p.setNombrePublico(nombre);p.setVinculacionRevisada(false);return p;}
 private PerfilJugador guardar(PerfilJugador p){try(Connection c=conexiones.obtener()){perfiles.guardar(c,p);return p;}catch(SQLException e){throw new RuntimeException("No se pudo crear el perfil deportivo.",e);}}
 public PerfilJugador actualizarPreferenciasPorCliente(long clienteId,boolean disponible,boolean invitaciones){if(clienteId<=0)throw new IllegalArgumentException("El cliente es inválido.");try(Connection c=conexiones.obtener()){c.setAutoCommit(false);try{PerfilJugador p=perfiles.buscarPorCliente(c,clienteId);if(p==null||!p.isActivo())throw new PerfilDeportivoNoVinculadoException();p.setDisponibleParaJugar(disponible);p.setAceptaInvitaciones(invitaciones);perfiles.guardar(c,p);c.commit();return p;}catch(RuntimeException|SQLException e){rollback(c,e);throw e;}finally{auto(c);}}catch(SQLException e){throw new RuntimeException("No se pudieron actualizar las preferencias deportivas.",e);}}
 public PerfilJugador actualizarPerfil(long perfilId,String nombre,PosicionJugador posicion,boolean disponible,boolean invitaciones){try(Connection c=conexiones.obtener()){PerfilJugador p=requerirPerfil(c,perfilId);p.setNombrePublico(nombre);p.setPosicionPreferida(posicion);p.setDisponibleParaJugar(disponible);p.setAceptaInvitaciones(invitaciones);perfiles.guardar(c,p);return p;}catch(SQLException e){throw new RuntimeException("No se pudo actualizar el perfil deportivo.",e);}}
 public PerfilJugador vincularCliente(long perfilId,long clienteId,String nombre,long usuarioId,boolean administrador){if(!administrador)throw new SecurityException("Solo un administrador puede vincular perfiles.");if(clienteId<=0||usuarioId<=0)throw new IllegalArgumentException("Cliente y responsable son obligatorios.");try(Connection c=conexiones.obtener()){c.setAutoCommit(false);try{PerfilJugador p=requerirPerfil(c,perfilId);if(p.getEstado()!=EstadoPerfilJugador.PROVISIONAL)throw new IllegalArgumentException("El perfil ya está vinculado.");PerfilJugador existente=perfiles.buscarPorCliente(c,clienteId);if(existente!=null&&existente.getId()!=perfilId)throw new IllegalArgumentException("El cliente ya tiene un perfil deportivo.");p.setClienteId(clienteId);p.setEstado(EstadoPerfilJugador.DEFINITIVO);p.setNombrePublico(nombre);p.setVinculacionRevisada(true);p.setUsuarioRevisionId(usuarioId);p.setFechaRevision(LocalDateTime.now());perfiles.guardar(c,p);c.commit();return p;}catch(RuntimeException|SQLException e){rollback(c,e);throw e;}finally{auto(c);}}catch(SQLException e){throw new RuntimeException("No se pudo vincular el perfil.",e);}}
 public PerfilJugador marcarVinculacionRevisada(long perfilId,long usuarioId,boolean administrador){if(!administrador)throw new SecurityException("Solo un administrador puede revisar identidades.");if(usuarioId<=0)throw new IllegalArgumentException("El responsable es obligatorio.");try(Connection c=conexiones.obtener()){PerfilJugador p=requerirPerfil(c,perfilId);if(p.getEstado()!=EstadoPerfilJugador.DEFINITIVO)throw new IllegalArgumentException("Primero asociá una ficha de cliente.");p.setVinculacionRevisada(true);p.setUsuarioRevisionId(usuarioId);p.setFechaRevision(LocalDateTime.now());perfiles.guardar(c,p);return p;}catch(SQLException e){throw new RuntimeException("No se pudo confirmar la identidad.",e);}}
 public PerfilJugador cambiarActivo(long perfilId,boolean activo,boolean administrador){if(!administrador)throw new SecurityException("Solo un administrador puede cambiar el estado del perfil.");try(Connection c=conexiones.obtener()){PerfilJugador p=requerirPerfil(c,perfilId);p.setActivo(activo);perfiles.guardar(c,p);return p;}catch(SQLException e){throw new RuntimeException("No se pudo cambiar el estado del perfil.",e);}}
 public JugadorCategoria asignarCategoria(long perfilId,long categoriaId,LocalDate desde,OrigenJugadorCategoria origen,String motivo,Long usuarioId){if(perfilId<=0||categoriaId<=0||desde==null||origen==null||vacio(motivo))throw new IllegalArgumentException("La asignación deportiva es incompleta.");try(Connection c=conexiones.obtener()){c.setAutoCommit(false);try{requerirPerfil(c,perfilId);CategoriaDeportiva cat=categorias.buscar(c,categoriaId);if(cat==null||!cat.isActivo())throw new IllegalArgumentException("La categoría no existe o está inactiva.");JugadorCategoria vigente=historial.buscarVigente(c,perfilId);if(vigente!=null&&desde.isBefore(vigente.getFechaDesde()))throw new IllegalArgumentException("La nueva vigencia no puede comenzar antes que la categoría actual.");if(vigente!=null&&vigente.getCategoriaDeportivaId()==categoriaId&&desde.equals(vigente.getFechaDesde()))throw new IllegalArgumentException("La categoría y la fecha ya coinciden con la vigencia actual.");historial.finalizarVigente(c,perfilId,desde.minusDays(1));JugadorCategoria x=new JugadorCategoria();x.setPerfilJugadorId(perfilId);x.setCategoriaDeportivaId(categoriaId);x.setFechaDesde(desde);x.setEstado(EstadoJugadorCategoria.VIGENTE);x.setOrigen(origen);x.setMotivo(limpiar(motivo));x.setUsuarioResponsableId(usuarioId);historial.guardar(c,x);c.commit();return x;}catch(RuntimeException|SQLException e){rollback(c,e);throw e;}finally{auto(c);}}catch(SQLException e){throw new RuntimeException("No se pudo asignar la categoría deportiva.",e);}}
 public void cerrarCategoria(long perfilId,LocalDate hasta,EstadoJugadorCategoria estado,String motivo,String observaciones,Long usuarioId,boolean administrador){if(!administrador)throw new SecurityException("Solo un administrador puede cerrar categorías.");if(estado!=EstadoJugadorCategoria.SUSPENDIDA&&estado!=EstadoJugadorCategoria.FINALIZADA)throw new IllegalArgumentException("El estado de cierre no es válido.");if(hasta==null||vacio(motivo))throw new IllegalArgumentException("Fecha y motivo son obligatorios.");try(Connection c=conexiones.obtener()){c.setAutoCommit(false);try{requerirPerfil(c,perfilId);JugadorCategoria vigente=historial.buscarVigente(c,perfilId);if(vigente==null)throw new IllegalArgumentException("El jugador no tiene una categoría vigente.");if(hasta.isBefore(vigente.getFechaDesde()))throw new IllegalArgumentException("La fecha de cierre no puede ser anterior al inicio.");historial.cerrarVigente(c,perfilId,hasta,estado,limpiar(motivo),limpiarOpcional(observaciones),usuarioId);c.commit();}catch(RuntimeException|SQLException e){rollback(c,e);throw e;}finally{auto(c);}}catch(SQLException e){throw new RuntimeException("No se pudo cerrar la categoría.",e);}}
 private PerfilJugador requerirPerfil(Connection c,long id){if(id<=0)throw new IllegalArgumentException("El perfil no es válido.");PerfilJugador p=perfiles.buscar(c,id);if(p==null)throw new IllegalArgumentException("El perfil no existe.");return p;}
 private boolean vacio(String x){return x==null||x.isBlank();} private String limpiar(String x){return x.trim().replaceAll("\s+"," ");} private String limpiarOpcional(String x){return vacio(x)?null:limpiar(x);} private void rollback(Connection c,Exception e){try{c.rollback();}catch(SQLException r){e.addSuppressed(r);}}private void auto(Connection c){try{c.setAutoCommit(true);}catch(SQLException ignored){}}
 public static class PerfilDeportivoNoVinculadoException extends IllegalArgumentException{public PerfilDeportivoNoVinculadoException(){super("Tu cuenta todavía no tiene un perfil deportivo vinculado.");}}
 @FunctionalInterface public interface ProveedorConexion{Connection obtener()throws SQLException;}
}
